package org.ninelym.layla.inference

import java.io.File
import java.util.concurrent.atomic.AtomicBoolean
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import org.ninelym.llm.ChatMessage
import org.ninelym.llm.GenerationOptions
import org.ninelym.llm.LanguageModel
import org.ninelym.llm.LanguageModels
import org.ninelym.llm.OpenAICompatibleModel
import org.ninelym.llm.PersonaPrompt

/**
 * Layla's conversational inference service.
 *
 * Every response is generated by the configured language model (a locally served model such
 * as llama.cpp server/Ollama, or a remote API) via [LanguageModels]. There is no offline or
 * placeholder answer: if no model is available, calls fail.
 */
class LaylaInferenceService(
    private val modelProvider: () -> Result<LanguageModel> = { LanguageModels.current() }
) {

    private val isInitialized = AtomicBoolean(false)
    private val isInferencing = AtomicBoolean(false)
    private val scope = CoroutineScope(Dispatchers.Default + SupervisorJob())

    private val _modelState = MutableStateFlow<ModelState>(ModelState.Unloaded)
    val modelState: StateFlow<ModelState> = _modelState

    private var model: LanguageModel? = null
    private var currentModel: ModelInfo? = null
    private val conversationHistory = mutableListOf<ConversationTurn>()

    /**
     * Connect to the configured model and confirm it is being served.
     */
    suspend fun initialize(config: InferenceConfig = InferenceConfig.default()): Result<Unit> {
        if (isInitialized.get()) return Result.success(Unit)
        return connect(modelProvider()).onSuccess {
            isInitialized.set(true)
            _modelState.value = ModelState.Ready
        }.onFailure {
            _modelState.value = ModelState.Error(it.message ?: "Initialization failed")
        }
    }

    /**
     * Select a model by its id on the configured server (e.g. "llama3.2" on Ollama). On-device
     * GGUF loading isn't packaged in this build, so a local file path is rejected rather than
     * pretending to load it.
     */
    suspend fun loadModel(modelPath: String, quantization: Quantization? = null): Result<Unit> {
        _modelState.value = ModelState.Loading
        if (File(modelPath).isFile) {
            val error = IllegalArgumentException(
                "On-device model files aren't supported in this build; serve $modelPath with a local " +
                    "llama.cpp server or Ollama and configure its endpoint instead."
            )
            _modelState.value = ModelState.Error(error.message!!)
            return Result.failure(error)
        }
        val base = modelProvider().getOrElse { _modelState.value = ModelState.Error(it.message ?: ""); return Result.failure(it) }
        val selected = (base as? OpenAICompatibleModel)
            ?.let { OpenAICompatibleModel(it.config.copy(model = modelPath)) }
            ?: base.takeIf { it.modelId == modelPath }
        if (selected == null) {
            val error = IllegalArgumentException("Model $modelPath is not available from the configured provider")
            _modelState.value = ModelState.Error(error.message!!)
            return Result.failure(error)
        }
        return connect(Result.success(selected), quantization).onSuccess { isInitialized.set(true) }
    }

    private suspend fun connect(provided: Result<LanguageModel>, quantization: Quantization? = null): Result<Unit> = runCatching {
        val candidate = provided.getOrThrow()
        if (candidate is OpenAICompatibleModel) {
            val served = candidate.listModels().getOrThrow()
            if (served.isNotEmpty() && candidate.modelId !in served) {
                throw IllegalStateException("Model ${candidate.modelId} is not served by ${candidate.config.baseUrl} (serving: $served)")
            }
        }
        model = candidate
        val info = ModelInfo(
            path = (candidate as? OpenAICompatibleModel)?.config?.baseUrl ?: candidate.modelId,
            name = candidate.modelId,
            quantization = quantization,
            sizeBytes = null,
            loadedAt = System.currentTimeMillis()
        )
        currentModel = info
        _modelState.value = ModelState.Loaded(info)
    }

    /**
     * Generate the next reply from the model, using the conversation so far as context.
     */
    suspend fun infer(
        prompt: String,
        parameters: InferenceParameters = InferenceParameters.default(),
        onToken: ((String) -> Unit)? = null
    ): Result<InferenceResponse> {
        if (!isInitialized.get()) {
            initialize().onFailure { return Result.failure(it) }
        }
        val activeModel = model ?: return Result.failure(IllegalStateException("No model loaded"))
        if (!isInferencing.compareAndSet(false, true)) {
            return Result.failure(IllegalStateException("Inference already in progress"))
        }
        try {
            conversationHistory.add(ConversationTurn("user", prompt, System.currentTimeMillis()))
            val response = performInference(activeModel, parameters, onToken).getOrElse {
                conversationHistory.removeAt(conversationHistory.lastIndex)
                return Result.failure(it)
            }
            conversationHistory.add(ConversationTurn("assistant", response.text, System.currentTimeMillis()))
            return Result.success(response)
        } finally {
            isInferencing.set(false)
        }
    }

    fun clearHistory() {
        conversationHistory.clear()
    }

    fun getHistory(): List<ConversationTurn> = conversationHistory.toList()

    suspend fun unloadModel(): Result<Unit> {
        model = null
        currentModel = null
        _modelState.value = ModelState.Ready
        return Result.success(Unit)
    }

    fun shutdown() {
        scope.cancel()
        isInitialized.set(false)
        model = null
        currentModel = null
        conversationHistory.clear()
        _modelState.value = ModelState.Unloaded
    }

    private suspend fun performInference(
        activeModel: LanguageModel,
        parameters: InferenceParameters,
        onToken: ((String) -> Unit)?
    ): Result<InferenceResponse> {
        val startTime = System.currentTimeMillis()
        val history = conversationHistory.takeLast(MAX_HISTORY_TURNS).map {
            if (it.role == "assistant") ChatMessage.assistant(it.content) else ChatMessage.user(it.content)
        }
        val messages = listOf(ChatMessage.system(parameters.systemPrompt ?: LAYLA.system())) + history
        var chunks = 0
        val options = GenerationOptions(
            temperature = parameters.temperature,
            topP = parameters.topP,
            maxTokens = parameters.maxTokens
        )
        return activeModel.chat(messages, options, onToken?.let { sink -> { token: String -> chunks++; sink(token) } })
            .map { text ->
                InferenceResponse(
                    text = text,
                    tokensGenerated = if (chunks > 0) chunks else text.split(Regex("\\s+")).count { it.isNotEmpty() },
                    inferenceTimeMs = System.currentTimeMillis() - startTime,
                    modelName = activeModel.modelId
                )
            }
    }

    companion object {
        private const val MAX_HISTORY_TURNS = 20

        val LAYLA = PersonaPrompt(
            name = "Layla",
            description = "a helpful, knowledgeable, friendly and empathetic AI assistant who runs on the user's device and respects their privacy.",
            rules = listOf("Answer the user's actual message; be concise unless detail is asked for.")
        )
    }
}

/**
 * Model state
 */
sealed class ModelState {
    object Unloaded : ModelState()
    object Ready : ModelState()
    object Loading : ModelState()
    data class Loaded(val info: ModelInfo) : ModelState()
    data class Error(val message: String) : ModelState()
}

/**
 * Model information. For a served model, [path] is the endpoint URL; quantization and size are
 * unknown unless the server reports them.
 */
data class ModelInfo(
    val path: String,
    val name: String,
    val quantization: Quantization?,
    val sizeBytes: Long?,
    val loadedAt: Long
)

/**
 * Model quantization levels
 */
enum class Quantization {
    Q4_0,  // 4-bit quantization (smallest)
    Q5_0,  // 5-bit quantization
    Q8_0,  // 8-bit quantization
    F16,   // 16-bit float
    F32    // 32-bit float (largest, most accurate)
}

/**
 * Inference configuration
 */
data class InferenceConfig(
    val enableGPUAcceleration: Boolean = true,
    val numThreads: Int = 4,
    val memoryLimit: Long = 2L * 1024 * 1024 * 1024 // 2GB
) {
    companion object {
        fun default() = InferenceConfig()
    }
}

/**
 * Inference parameters
 */
data class InferenceParameters(
    val temperature: Float = 0.7f,
    val topP: Float = 0.9f,
    val topK: Int = 40,
    val maxTokens: Int = 512,
    val contextSize: Int = 2048,
    val repeatPenalty: Float = 1.1f,
    val seed: Int = -1,
    /** Overrides Layla's default persona prompt. */
    val systemPrompt: String? = null
) {
    companion object {
        fun default() = InferenceParameters()
    }
}

/**
 * Conversation turn in history
 */
data class ConversationTurn(
    val role: String,
    val content: String,
    val timestamp: Long
)

/**
 * Inference response
 */
data class InferenceResponse(
    val text: String,
    val tokensGenerated: Int,
    val inferenceTimeMs: Long,
    val modelName: String
)
